"""ex11 单轮多 tool_calls 的并发执行与按 call_id 归位合并。"""
import concurrent.futures

TABLE = {"lookup_cn": "1411780000", "lookup_fr": "Paris",
         "add": "4600", "lookup_jp": "125700000"}


def tool_impl(name, arg):
    return TABLE.get(arg, "NOT_FOUND")


CALLS = [
    {"call_id": "c1", "name": "lookup", "arg": "lookup_cn"},
    {"call_id": "c2", "name": "lookup", "arg": "lookup_fr"},
    {"call_id": "c3", "name": "add", "arg": "add"},
    {"call_id": "c4", "name": "lookup", "arg": "lookup_jp"},
]


def run_parallel(calls):
    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as ex:
        futs = {ex.submit(tool_impl, c["name"], c["arg"]): c["call_id"] for c in calls}
        return [(futs[f], f.result()) for f in concurrent.futures.as_completed(futs)]


def merge(raw):
    """按 call_id 归位：结果与到达顺序无关。"""
    return {cid: val for cid, val in raw}


if __name__ == "__main__":
    raw = run_parallel(CALLS)
    merged = merge(raw)
    print("并发执行 call 数 = %d" % len(raw))
    print("按 call_id 归位后 = %s" % {k: merged[k] for k in sorted(merged)})

    a = merge([("c1", "1411780000"), ("c2", "Paris"), ("c3", "4600"), ("c4", "125700000")])
    b = merge([("c4", "125700000"), ("c3", "4600"), ("c2", "Paris"), ("c1", "1411780000")])
    print("乱序合并结果一致 = %s" % (a == b))

    shuffled = [("c3", "4600"), ("c1", "1411780000"), ("c4", "125700000"), ("c2", "Paris")]
    naive = {c["call_id"]: v for c, (_, v) in zip(CALLS, shuffled)}   # 按位置错配
    print("按位置合并会产生错误映射 = %s" % (naive != merged))
